---@class Page_PopUpGiftViewBase
Page_PopUpGiftViewBase = class("Page_PopUpGiftViewBase")

---@param data PopUpGiftData
function Page_PopUpGiftViewBase.CreatePageGiftView(type,parentPref)
    local page
    if type == PopUpGiftType.Level then
        page = Page_PopUpGiftLevelView()
    elseif type == PopUpGiftType.Luck  then
        page = Page_PopUpGiftLuckView()
    elseif type == PopUpGiftType.Failure  then
        page = Page_PopUpGiftFailureView()
    elseif type == PopUpGiftType.Sticker  then
        page = Page_PopUpGiftStickerView()
    end
    if page then
        Page_PopUpGiftViewBase.initialize(page,parentPref)
        page:OnAwake()
    end
    return page
end

function Page_PopUpGiftViewBase:initialize(parentPref)
    if self and parentPref  then
        self.parentPref = parentPref
        ---@type PopUpGiftData
        self.canvasGroup = UIUtil.GetTypeChildWightByParent(self:GetPageName(), self.parentPref, typeof(CanvasGroup))
        self.gameObject = self.canvasGroup.gameObject
        self:SetCanvasGroup(false)
    else
        logWarn("该继承未初始化基类")
    end
end

---@param data PopUpGiftData
function Page_PopUpGiftViewBase:Open(data)
    ---@type PopUpGiftData
    self.data=data
    self:SetCanvasGroup(true)
    self:OnOpen()
end

function Page_PopUpGiftViewBase:Close()
    self:SetCanvasGroup(false)
    self:OnClose()
end

function Page_PopUpGiftViewBase:SetCanvasGroup(active)
    UIUtil.ShowCanvasGroup(self.canvasGroup,active)
end

