function Page_PopUpGiftViewBase:OnOpen()
    CommonHelper:GetComponentSetUITexture("pageBg", self.gameObject, self.data.config.giftIcon..".png", self:GetUIModuleID())
    self.PurchaseBtn = CommonHelper:HButtonSetCallback("PurchaseBtn", self.gameObject, function()
        self:OnPurchaseBtnClick()
    end)
    ---@type dictcharge_config_cell
    local cfg= CommonHelper:GetChargeCfgByAreaAndItemId(self.data.config.C_ID)
    CommonHelper:SetBtnTextMeshIsRmbOrToken(self.PurchaseBtn,cfg)
    self:OnInitScrollView()
end

function Page_PopUpGiftViewBase:OnInitScrollView()
    CommonHelper:InitMoreRowScrollView(self.InfoBaseScroll, #self.data.AwardList, 1, function(index, item, scrollview)
        local param = Param_ItemArticleParam()
        param.count = self.data.AwardList[index + 1].num
        CommonHelper:SetItemComGroup(item, self:GetUIModuleID(), self.data.AwardList[index + 1].id, param, function()
            CommonHelper:ShowPartInfoByCfgId(self.data.AwardList[index + 1].id, self:GetUIModuleID())
        end)
    end)
end

